@@ -1,12 +1,68 @@
+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const SESSIONS_DIR = path.join(process.cwd(), ".sessions");
 const store = new Map<string, Entry>();

+const ensureDir = (): void => {
+  if (!fs.existsSync(SESSIONS_DIR)) {
+    fs.mkdirSync(SESSIONS_DIR, { recursive: true });
+  }
+};
+
+const getPath = (key: string): string => path.join(SESSIONS_DIR, `${key}.json`);
+
+const loadFromDisk = (): void => {
+  ensureDir();
+  try {
+    const files = fs.readdirSync(SESSIONS_DIR);
+    for (const file of files) {
+      if (file.endsWith(".json")) {
+        try {
+          const data = JSON.parse(fs.readFileSync(path.join(SESSIONS_DIR, file), "utf-8")) as Entry;
+          const key = file.slice(0, -5);
+          if (data.expiresAt > Date.now()) {
+            store.set(key, data);
+          }
+        } catch {
+          // Ignore corrupt files
+        }
+      }
+    }
+  } catch {
+    // Ignore errors reading directory
+  }
+};
+
+const saveToDisk = (key: string, entry: Entry): void => {
+  ensureDir();
+  try {
+    fs.writeFileSync(getPath(key), JSON.stringify(entry));
+  } catch {
+    // Log error but don't fail the operation
+  }
+};
+
+const removeFromDisk = (key: string): void => {
+  try {
+    fs.unlinkSync(getPath(key));
+  } catch {
+    // Ignore if file doesn't exist
+  }
+};
+
+// Load sessions from disk on startup
+loadFromDisk();
+
 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  const entry = { value, expiresAt: Date.now() + ttlMs };
+  store.set(key, entry);
+  saveToDisk(key, entry);
 };

 export const get = (key: string): string | null => {
@@ -14,6 +70,7 @@ export const get = (key: string): string | null => {
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    removeFromDisk(key);
     return null;
   }
   return entry.value;
